import unittest

from solucao import posicao_de
from solucao import quantas_vezes


class TestAcharAPosicao(unittest.TestCase):
    def test_posicao_do_item(self):
        """posicao_de devolve a posicao do item"""
        self.assertTrue(posicao_de(["uva", "pera", "manga"], "manga") == 2)

    def test_posicao_do_primeiro(self):
        """posicao_de devolve a posicao do primeiro item"""
        self.assertTrue(posicao_de(["uva", "pera", "manga"], "uva") == 0)

    def test_conta_as_vezes(self):
        """quantas_vezes devolve quantas vezes o item aparece"""
        self.assertTrue(quantas_vezes(["ana", "bia", "ana"], "ana") == 2)

    def test_count_de_item_ausente(self):
        """quantas_vezes devolve 0 para item que nao esta"""
        self.assertTrue(quantas_vezes(["ana", "bia"], "caio") == 0)

